<?php

namespace App\Enums;

enum QuoteStatus: string
{
    case Draft = 'draft';
    case PendingReview = 'pending_review';
    case Approved = 'approved';
    case Rejected = 'rejected';
    case Published = 'published';
    /** Generated by the workflow and hidden from its author until the last step is done. */
    case AwaitingUnlock = 'awaiting_unlock';
}
